	@Test
	void unknownAnswerRelationRetainsTheIndependentPlan() {
		IRI outsideVocabulary = VF.createIRI(RDF.NAMESPACE, "_123");
		IRI vocabularyMember = VF.createIRI(RDF.NAMESPACE, "_1");
		IRI containerProperty = RDFS.CONTAINERMEMBERSHIPPROPERTY;
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH), List.of(
				VF.createStatement(vocabularyMember, RDF.TYPE, containerProperty, GRAPH))) {
			@Override
			public StatementRestrictionSourcePlan prepareStatementRestriction(StatementPattern pattern,
					QueryEvaluationContext context, RestrictionLayout scope) {
				return null;
			}

			@Override
			protected Stream<Statement> matchingStatements(Resource subject, IRI predicate, Value object,
					List<Resource> requested) {
				if (outsideVocabulary.equals(subject) && RDF.TYPE.equals(predicate) && containerProperty.equals(object)
						&& requested.contains(GRAPH)) {
					return Stream.of(VF.createStatement(outsideVocabulary, RDF.TYPE, containerProperty, GRAPH));
				}
				return super.matchingStatements(subject, predicate, object, requested);
			}
		};
		String query = "VALUES ?s { <" + outsideVocabulary + "> } GRAPH :G { ?s <" + RDF.TYPE + "> <"
				+ containerProperty + "> }";
		try (var ground = source.getStatements(outsideVocabulary, RDF.TYPE, containerProperty, GRAPH)) {
			assertThat(ground.hasNext()).isTrue();
		}
		source.resetObservations();
		assertThat(evaluate(source, parse(query), null, EmptyBindingSet.getInstance(), GraphRestrictionMode.AUTO))
				.isEmpty();
		assertThat(source.accesses).containsExactly(new Access(null, RDF.TYPE, containerProperty, List.of(GRAPH)));

		source.resetObservations();
		assertThatThrownBy(() -> evaluate(source, parse(query))).isInstanceOf(QueryEvaluationException.class);
		assertThat(source.accesses).isEmpty();
	}

