	@Test
	void oneHundredKeysReadOneHundredQuadsFromAMillionRowRelation() {
		int statementCount = 1_000_000;
		int keyCount = 100;
		IRI object = iri("object");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH), List.of()) {
			@Override
			protected Stream<Statement> matchingStatements(Resource subject, IRI predicate, Value objectFilter,
					List<Resource> requested) {
				if ((predicate != null && !PREDICATE.equals(predicate))
						|| (objectFilter != null && !object.equals(objectFilter))
						|| (!requested.isEmpty() && !requested.contains(GRAPH))) {
					return Stream.empty();
				}
				if (subject == null) {
					return IntStream.range(0, statementCount)
							.mapToObj(index -> VF.createStatement(iri("s" + index), PREDICATE, object, GRAPH));
				}
				if (subject instanceof IRI name && NAMESPACE.equals(name.getNamespace())
						&& name.getLocalName().matches("s[0-9]{1,6}")) {
					int index = Integer.parseInt(name.getLocalName().substring(1));
					if (index < statementCount && iri("s" + index).equals(name)) {
						return Stream.of(VF.createStatement(name, PREDICATE, object, GRAPH));
					}
				}
				return Stream.empty();
			}
		};
		StringBuilder values = new StringBuilder();
		List<BindingSet> expected = new ArrayList<>(keyCount);
		List<Access> accesses = new ArrayList<>(keyCount);
		for (int index = 0; index < keyCount; index++) {
			String localName = "s" + (index * 9_913);
			IRI subject = iri(localName);
			values.append(':').append(localName).append(' ');
			expected.add(row(subject, object));
			accesses.add(new Access(subject, PREDICATE, null, List.of(GRAPH)));
		}
		assertThat(evaluate(source, parse("VALUES ?s { " + values + " } GRAPH :G { ?s :p ?o }")))
				.containsExactlyInAnyOrderElementsOf(expected);
		assertThat(source.accesses).containsExactlyInAnyOrderElementsOf(accesses);
		assertThat(source.statementRows).isEqualTo(keyCount);
	}

	@Test
	void nilAliasSelectionKeepsItsOriginalGraphProvenance() {
		IRI subject = iri("selected");
		IRI defaultObject = iri("default");
		IRI physicalObject = iri("physical");
		for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
			RecordingTripleSource source = new RecordingTripleSource(List.of(alias), List.of(
					VF.createStatement(subject, PREDICATE, defaultObject),
					VF.createStatement(subject, PREDICATE, physicalObject, alias)));
			SimpleDataset explicit = new SimpleDataset();
			explicit.addNamedGraph(alias);
			String join = "VALUES (?g ?s) { (<" + alias + "> :selected) } GRAPH ?g { ?s :p ?o }";
			MapBindingSet apiBindings = new MapBindingSet();
			apiBindings.addBinding("g", alias);

			assertAliasRoute(source, join, null, EmptyBindingSet.getInstance(), subject, physicalObject, alias);
			assertAliasRoute(source, join, explicit, EmptyBindingSet.getInstance(), subject, defaultObject, null);
			assertAliasRoute(source, join, null, apiBindings, subject, defaultObject, null);
			assertAliasRoute(source, join, explicit, apiBindings, subject, physicalObject, alias);
			String fixedJoin = "VALUES ?s { :selected } GRAPH <" + alias + "> { ?s :p ?o }";
			assertAliasRoute(source, fixedJoin, null, EmptyBindingSet.getInstance(), subject, defaultObject, null);
			assertAliasRoute(source, fixedJoin, explicit, EmptyBindingSet.getInstance(), subject, physicalObject,
					alias);
		}
	}

