		Value triple = VF.createTripleTerm(iri("a"), PREDICATE, iri("b"));
		List<TermCase> cases = List.of(
				new TermCase(VF.createLiteral("label", "EN-gb"), VF.createLiteral("label", "en-GB"),
						VF.createLiteral("label", "en-US")),
				new TermCase(directed, directed, VF.createLiteral("label", "en", BaseDirection.RTL)),
				new TermCase(VF.createBNode("shared"), VF.createBNode("shared"), VF.createBNode("other")),
				new TermCase(triple, triple, VF.createTripleTerm(iri("a"), PREDICATE, iri("other"))));
