	@Test
	void optionalAndMinusProbeStorageWithTheOriginalLeftWitness() {
		IRI a = iri("a");
		IRI key = iri("key");
		IRI observed = iri("observed");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH), List.of(
				VF.createStatement(a, PREDICATE, key, GRAPH),
				VF.createStatement(a, observed, iri("unequal"), GRAPH),
				VF.createStatement(iri("unrelated"), observed, iri("outside"), GRAPH)));
		for (String operator : List.of("OPTIONAL", "MINUS")) {
			String query = "VALUES (?key ?x) { (:key :outside) } GRAPH :G { "
					+ "?s :p ?key " + operator + " { ?s :observed ?x } }";
			var algebra = parse("?s ?x", query);
			assertThat(evaluate(source, algebra.clone(), null, EmptyBindingSet.getInstance(),
					GraphRestrictionMode.FORCE_INDEPENDENT)).as(operator).isEmpty();
			source.resetObservations();
			assertThat(evaluate(source, algebra)).as(operator).isEmpty();
			assertThat(source.accesses).as(operator)
					.containsExactly(
							new Access(null, PREDICATE, key, List.of(GRAPH)),
							new Access(a, observed, null, List.of(GRAPH)));
			source.resetObservations();
		}
	}

	@Test
	void witnessOnlyRightKeyDoesNotSelectAnExternalGraphProbe() {
		IRI selected = iri("selected");
		IRI object = iri("object");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH),
				List.of(VF.createStatement(selected, PREDICATE, object, GRAPH)));
		TupleExpr expression = parse("?s ?x", """
				VALUES ?x { :object }
				GRAPH :G { VALUES ?s { :selected } OPTIONAL { ?s :p ?x } }
				""");
		List<Join> joins = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				if (join.getRightArg() instanceof Graph) {
					joins.add(join);
				}
				super.meet(join);
			}
		});
		assertThat(joins).hasSize(1);
		Join join = joins.getFirst();
		assertThat(evaluate(source, expression)).containsExactly(row(Map.of("s", selected, "x", object)));
		assertThat(join.getAlgorithmName()).isEqualTo("HashJoinIteration");
		assertThat(RestrictionCompiler.hasPotentialSeekFrom(join.getRightArg(), join.getLeftArg())).isFalse();
	}

