	@Test
	void limitAndEmptyOuterInputPreserveRequiredServiceDemand() {
		IRI subject = iri("selected");
		IRI object = iri("object");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH, iri("H")),
				List.of(VF.createStatement(subject, PREDICATE, object, GRAPH)));
		String eager = "VALUES ?s { :selected } GRAPH :G { { ?s :p ?o } UNION { " + FAILING_SERVICE + " } }";
		String emptyLeft = "VALUES ?s { } GRAPH :G { { ?s :p ?o } UNION { GRAPH :H { "
				+ FAILING_SERVICE + " } } }";
		for (GraphRestrictionMode mode : List.of(GraphRestrictionMode.FORCE_INDEPENDENT, GraphRestrictionMode.AUTO)) {
			AtomicInteger calls = new AtomicInteger();
			var strategy = failingServiceStrategy(source, mode, calls);
			assertThatThrownBy(() -> evaluate(strategy, parse("?s ?o", eager, "LIMIT 1"),
					EmptyBindingSet.getInstance()))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining(CONTROLLED_SERVICE_FAILURE);
			assertThat(calls).hasValue(1);

			calls.set(0);
			var emptyOuter = failingServiceStrategy(source, mode, calls);
			assertThatThrownBy(() -> evaluate(emptyOuter, parse(emptyLeft), EmptyBindingSet.getInstance()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining(CONTROLLED_SERVICE_FAILURE);
			assertThat(calls).hasValue(1);
		}
	}

	@Test
	void closeAndLimitDoNotDemandADeferredServiceAfterTheFirstResult() {
		IRI subject = iri("selected");
		IRI object = iri("object");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH, iri("H")),
				List.of(VF.createStatement(subject, PREDICATE, object, GRAPH)));
		String query = "VALUES ?s { :selected } GRAPH :G { { ?s :p ?o } UNION { GRAPH :H { "
				+ FAILING_SERVICE + " } } }";
		for (GraphRestrictionMode mode : List.of(GraphRestrictionMode.FORCE_INDEPENDENT, GraphRestrictionMode.AUTO)) {
			AtomicInteger calls = new AtomicInteger();
			var zero = failingServiceStrategy(source, mode, calls);
			zero.precompile(parse(query)).evaluate(EmptyBindingSet.getInstance()).close();
			assertThat(calls).hasValue(0);

			var partial = failingServiceStrategy(source, mode, calls);
			try (var rows = partial.precompile(parse(query)).evaluate(EmptyBindingSet.getInstance())) {
				assertThat(rows.next()).isEqualTo(row(subject, object));
			}
			assertThat(calls).hasValue(0);

			var limited = failingServiceStrategy(source, mode, calls);
			assertThat(evaluate(limited, parse("?s ?o", query, "LIMIT 1"), EmptyBindingSet.getInstance()))
					.containsExactly(row(subject, object));
			assertThat(calls).hasValue(0);

			var fullyDemanded = failingServiceStrategy(source, mode, calls);
			assertThatThrownBy(() -> evaluate(fullyDemanded, parse(query), EmptyBindingSet.getInstance()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining(CONTROLLED_SERVICE_FAILURE);
			assertThat(calls).hasValue(1);
		}
	}

	private static DefaultEvaluationStrategy failingServiceStrategy(RecordingTripleSource source,
			GraphRestrictionMode mode, AtomicInteger calls) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, endpoint -> {
			calls.incrementAndGet();
			throw new QueryEvaluationException(CONTROLLED_SERVICE_FAILURE);
		});
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT.withGraphRestrictionMode(mode));
		return strategy;
	}

	@Test
	void unsafePathMasksPreserveOriginalIdentityMultiplicityBesideARealProbe() {
		IRI absent = iri("absent");
		IRI witness = iri("witness");
		IRI probe = iri("probe");
		IRI marker = iri("marker");
		IRI otherGraph = iri("H");
		IRI a = iri("a");
		IRI b = iri("b");
		RecordingTripleSource source = new RecordingTripleSource(List.of(GRAPH, otherGraph), List.of(
				VF.createStatement(a, PREDICATE, b, GRAPH),
				VF.createStatement(a, absent, b, GRAPH),
				VF.createStatement(absent, PREDICATE, b, otherGraph),
				VF.createStatement(a, PREDICATE, VF.createTripleTerm(absent, PREDICATE, b), GRAPH),
				VF.createStatement(witness, probe, marker, GRAPH)));
		BindingSet witnessRow = row(Map.of("x", absent, "y", absent, "o", marker));
		BindingSet identityRow = row(Map.of("x", absent, "y", absent));

		assertUnsafePath(source, ":absent (:p* | (:p*/:q*)) ?y", witness, probe, List.of(witnessRow, identityRow));
		assertUnsafePath(source, "?x (:p*/:q*) ?y", witness, probe, List.of(witnessRow));
		assertUnsafePath(source, "?x (:p*/:q*) ?x", witness, probe, List.of(witnessRow));
	}

	private static void assertUnsafePath(RecordingTripleSource source, String path, IRI witness, IRI probe,
			List<BindingSet> expected) {
		String query = "VALUES (?x ?y ?w) { (:absent :absent :witness) } "
				+ "GRAPH :G { { " + path + " } UNION { ?w :probe ?o } }";
		source.resetObservations();
		assertThat(evaluate(source, parse("?x ?y ?o", query), null, EmptyBindingSet.getInstance(),
				GraphRestrictionMode.FORCE_INDEPENDENT)).as(path).containsExactlyInAnyOrderElementsOf(expected);

		source.resetObservations();
		assertThat(evaluate(source, parse("?x ?y ?o", query))).as(path).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(source.accesses).contains(new Access(witness, probe, null, List.of(GRAPH)));
	}

